records.logicalInterface:
datatype Constraint = C(kind: Kind, data: seq<Byte>)
  // The Solidity ABI decoder is an explicit environmental input. It may reject
  // or return any finite decoded list; no canonical-encoding assumption is made.

datatype CallDecode = MalformedCall | DecodedCall(target: Address, data: seq<Byte>)
  // Requests record attempted calls (including the code-presence check), not
  // just successful EVM calls. Equal requests at different histories can differ.

datatype ReturnResult = BytesReturned(bytes: seq<Byte>) | Rejected(error: Error)

  // LEN intentionally reads before refusing dynamic tuples/fixed arrays.
  // It bounds the footprint, but does not validate narrow words or array tails.

ghost method Navigate(t: seq<Byte>, data: seq<Byte>, path: seq<int>)
    returns (r: CursorResult)
    requires Uint(|t|) && Uint(|data|) && Uint(|path|)
    requires forall i :: 0 <= i < |path| ==> Sint(path[i])
    ensures r == Navigation(t,data,path)
    ensures |t| == 0 || t[0] != 40 ==> r == Stopped(InvalidTypeDescriptor(0))
    ensures |t| > 0 && t[0] == 40 && |path| == 0 ==> r == Stopped(InvalidNavigation(0))
    ensures |t| > 0 && t[0] == 40 && |path| > 0 ==>
              (var top := Parse(t,0,|t|);
               if top.BadDescriptor? then r == Stopped(InvalidTypeDescriptor(top.at))
               else if top.ArithmeticPanic? then r == Stopped(Error.Panic(17))
               else if top.end != |t| then r == Stopped(InvalidTypeDescriptor(top.end))
               else Admissible(top.syntax) && r == Steps(data,Cursor(top.syntax,0,0),path))
    ensures r.Moved? ==> Span(t,r.cursor) && Uint(r.cursor.base)
